import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":".vibator.json","description":"","frontmatter":{},"headers":[],"relativePath":"reference/configuration.md","filePath":"reference/configuration.md"}`),a={name:`reference/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="vibator-json" tabindex="-1"><code>.vibator.json</code> <a class="header-anchor" href="#vibator-json" aria-label="Permalink to “.vibator.json”">​</a></h1><p>This document is the reference of the <code>.vibator.json</code> configuration file: the fields it accepts and the way the framework loads rules, as they are provided by the base vibator framework.</p><p>A project adds a <code>.vibator.json</code> at its root. The file is optional and overrides the default configuration.</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to “Reference”">​</a></h2><ul><li><a href="#fields">Fields</a> — The top-level fields of the file.</li><li><a href="#rules">rules</a> — Per-rule overrides.</li><li><a href="#ruleconfig">RuleConfig</a> — The override one rule accepts.</li><li><a href="#loading">Loading</a> — How the framework finds and loads rules.</li></ul><hr><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to “Fields”">​</a></h2><p>The top-level fields of the file.</p><table tabindex="0"><thead><tr><th>Declaration</th><th>Description</th></tr></thead><tbody><tr><td>$schema?: string</td><td>The path or URL of the schema that validates this file.</td></tr><tr><td>extends?: string[]</td><td>Paths or package names of base configs to inherit.</td></tr><tr><td>plugins?: string[]</td><td>Paths or package names of rule modules that live outside <code>.vibator/</code>.</td></tr><tr><td>exclude?: string[]</td><td>Directory names to skip during file discovery, replacing the built-in defaults.</td></tr><tr><td>rules?: Record&lt;string, <a href="./rule-definition.html#severity">Severity</a> | <a href="#ruleconfig">RuleConfig</a>&gt;</td><td>Per-rule overrides, keyed by rule id.</td></tr></tbody></table><h2 id="rules" tabindex="-1">rules <a class="header-anchor" href="#rules" aria-label="Permalink to “rules”">​</a></h2><p>A rule entry is a <a href="#ruleconfig">RuleConfig</a>. A severity shorthand exists for convenience: a bare <a href="./rule-definition.html#severity">Severity</a> stands for that severity alone, so <code>{ &quot;no-deprecated-apis&quot;: &quot;off&quot; }</code> reads as <code>{ &quot;no-deprecated-apis&quot;: { &quot;severity&quot;: &quot;off&quot; } }</code>.</p><p>The framework validates every key against the loaded rules and reports an unknown rule id as an error.</p><h2 id="ruleconfig" tabindex="-1">RuleConfig <a class="header-anchor" href="#ruleconfig" aria-label="Permalink to “RuleConfig”">​</a></h2><p>The override one rule accepts.</p><table tabindex="0"><thead><tr><th>Declaration</th><th>Description</th></tr></thead><tbody><tr><td>severity?: <a href="./rule-definition.html#severity">Severity</a></td><td>The severity applied to this rule.</td></tr><tr><td>options?: object</td><td>The rule&#39;s options, validated by the rule&#39;s own schema.</td></tr><tr><td>docs?: string</td><td>The path to the guideline shown for this rule.</td></tr></tbody></table><p>A <code>docs</code> value resolves from the project root, such as <code>.vibator/docs/my-rule.md</code>, or from a package when prefixed with the package name, such as <code>vibator:docs/rules/no-deprecated-apis.md</code>.</p><h2 id="loading" tabindex="-1">Loading <a class="header-anchor" href="#loading" aria-label="Permalink to “Loading”">​</a></h2><p>How the framework finds and loads rules.</p><table tabindex="0"><thead><tr><th>Source</th><th>Loading</th></tr></thead><tbody><tr><td><code>.vibator/</code> folder</td><td>Every rule in the folder loads automatically.</td></tr><tr><td><code>plugins</code></td><td>Every module named in <code>plugins</code> loads from its path or package.</td></tr></tbody></table><p>Every loaded rule is configured by id in <a href="#rules">rules</a>. Each id stays unique across the two sources, and the framework reports a repeated id as an error.</p>`,20)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};